-- Volcando estructura para procedimiento logitrack.procedimiento_asignar_envio_a_viaje
DELIMITER //
CREATE PROCEDURE `procedimiento_asignar_envio_a_viaje`(
    IN id_del_viaje    INT,
    IN numero_de_envio INT
)
BEGIN
    DECLARE cantidad_asignaciones_existentes INT;

    SELECT COUNT(*) INTO cantidad_asignaciones_existentes
    FROM viaje_envio
    WHERE viaje_id = id_del_viaje
      AND nro_envio = numero_de_envio;

    IF cantidad_asignaciones_existentes > 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El envío ya está asignado a este viaje';
    ELSE
        VALUES (id_del_viaje, numero_de_envio);
        SELECT 'Envío asignado correctamente' AS mensaje;
    END IF;
END//
DELIMITER ;

-- Volcando estructura para procedimiento logitrack.procedimiento_cerrar_viaje
DELIMITER //
CREATE PROCEDURE `procedimiento_cerrar_viaje`(
    IN id_del_viaje          INT,
    IN fecha_de_llegada      DATETIME
)
BEGIN
    DECLARE viaje_existe INT;
    DECLARE viaje_ya_cerrado INT;

    SELECT COUNT(*) INTO viaje_existe
    FROM viaje
    WHERE viaje_id = id_del_viaje;

    IF viaje_existe = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El viaje no existe';
    END IF;

    SELECT COUNT(*) INTO viaje_ya_cerrado
    FROM viaje
    WHERE viaje_id = id_del_viaje
      AND fecha_llegada IS NOT NULL;

    IF viaje_ya_cerrado > 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El viaje ya fue cerrado anteriormente';
    END IF;

    UPDATE viaje
    SET fecha_llegada = fecha_de_llegada
    WHERE viaje_id = id_del_viaje;

    SELECT 'Viaje cerrado correctamente' AS mensaje,
           id_del_viaje AS viaje_id,
           fecha_de_llegada AS fecha_llegada_registrada;
END//
DELIMITER ;

-- Volcando estructura para procedimiento logitrack.procedimiento_crear_envio
DELIMITER //
CREATE PROCEDURE `procedimiento_crear_envio`(
    IN fecha_del_envio        DATE,
    IN peso_del_envio         DECIMAL(8,2),
    IN codigo_tipo_contenido  CHAR(3),
    IN dni_remitente          INT,
    IN dni_destinatario       INT,
    IN codigo_sucursal_origen VARCHAR(10),
    IN codigo_sucursal_destino VARCHAR(10),
    IN id_direccion_entrega   INT
)
BEGIN
    DECLARE numero_envio_creado INT;

        fecha_envio, peso_kg, tipo_cont_cod,
        remitente_dni, destinatario_dni,
        sucursal_orig_cod, sucursal_dest_cod,
        direccion_entrega_id
    ) VALUES (
        fecha_del_envio, peso_del_envio, codigo_tipo_contenido,
        dni_remitente, dni_destinatario,
        codigo_sucursal_origen, codigo_sucursal_destino,
        id_direccion_entrega
    );

    SET numero_envio_creado = LAST_INSERT_ID();

        nro_envio, sucursal_cod, estado, fecha_hora, observacion
    ) VALUES (
        numero_envio_creado, codigo_sucursal_origen,
        'En sucursal origen', NOW(),
        'Envío registrado automáticamente'
    );

    SELECT numero_envio_creado AS nro_envio_creado;
END//
DELIMITER ;

-- Volcando estructura para procedimiento logitrack.procedimiento_registrar_estado_envio
DELIMITER //
CREATE PROCEDURE `procedimiento_registrar_estado_envio`(
    IN numero_de_envio        INT,
    IN codigo_sucursal        VARCHAR(10),
    IN nuevo_estado           VARCHAR(30),
    IN observacion_del_estado TEXT
)
BEGIN
    DECLARE envio_existe INT;

    SELECT COUNT(*) INTO envio_existe
    FROM envio
    WHERE nro_envio = numero_de_envio;

    IF envio_existe = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El envío no existe';
    ELSE
            nro_envio, sucursal_cod, estado, fecha_hora, observacion
        ) VALUES (
            numero_de_envio, codigo_sucursal,
            nuevo_estado, NOW(),
            observacion_del_estado
        );

        SELECT 'Estado registrado correctamente' AS mensaje,
               numero_de_envio AS nro_envio,
               nuevo_estado AS estado_registrado;
    END IF;
END//
DELIMITER ;

-- Volcando estructura para procedimiento logitrack.procedimiento_resumen_por_sucursal
DELIMITER //
CREATE PROCEDURE `procedimiento_resumen_por_sucursal`()
BEGIN
    SELECT 
        s.sucursal_nombre,
        s.sucursal_cod,
        COUNT(e.nro_envio) AS total_envios
    FROM sucursal s
    LEFT JOIN envio e ON s.sucursal_cod = e.sucursal_orig_cod
    GROUP BY s.sucursal_cod, s.sucursal_nombre
    ORDER BY total_envios DESC;
END//
DELIMITER ;

