-- Volcando estructura para disparador logitrack.trigger_after_insert_envio
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trigger_after_insert_envio
AFTER INSERT ON envio
FOR EACH ROW
BEGIN
        nro_envio, sucursal_cod, estado, fecha_hora, observacion
    ) VALUES (
        NEW.nro_envio,
        NEW.sucursal_orig_cod,
        'En sucursal origen',
        NOW(),
        'Estado inicial registrado automáticamente por trigger'
    );
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- Volcando estructura para disparador logitrack.trigger_after_update_envio
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trigger_after_update_envio
AFTER UPDATE ON envio
FOR EACH ROW
BEGIN
    IF NEW.sucursal_dest_cod <> OLD.sucursal_dest_cod THEN
            nro_envio, sucursal_cod, estado, fecha_hora, observacion
        ) VALUES (
            NEW.nro_envio,
            NEW.sucursal_dest_cod,
            'Redirigido',
            NOW(),
            CONCAT('Destino cambiado de sucursal ', OLD.sucursal_dest_cod, ' a ', NEW.sucursal_dest_cod)
        );
    END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- Volcando estructura para disparador logitrack.trigger_before_delete_viaje
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trigger_before_delete_viaje
BEFORE DELETE ON viaje
FOR EACH ROW
BEGIN
    DECLARE cantidad_envios_asignados INT;

    SELECT COUNT(*) INTO cantidad_envios_asignados
    FROM viaje_envio
    WHERE viaje_id = OLD.viaje_id;

    IF cantidad_envios_asignados > 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'No se puede eliminar el viaje porque tiene envíos asignados';
    END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- Volcando estructura para disparador logitrack.trigger_before_insert_envio
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trigger_before_insert_envio
BEFORE INSERT ON envio
FOR EACH ROW
BEGIN
    IF NEW.peso_kg <= 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El peso del envío debe ser mayor a cero';
    END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- Volcando estructura para disparador logitrack.trigger_before_update_viaje
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trigger_before_update_viaje
BEFORE UPDATE ON viaje
FOR EACH ROW
BEGIN
    IF NEW.fecha_llegada IS NOT NULL AND NEW.fecha_llegada <= OLD.fecha_salida THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'La fecha de llegada debe ser posterior a la fecha de salida';
    END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `vista_clientes_con_envios`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vista_clientes_con_envios` AS SELECT
    c.cliente_dni,
    CONCAT(c.nombre, ' ', c.apellido) AS nombre_completo,
    c.mail,
    c.telefono,
    loc.localidad_nombre,
    prov.provincia_nombre,
    COUNT(DISTINCT e_rem.nro_envio) AS cantidad_envios_como_remitente,
    COUNT(DISTINCT e_dest.nro_envio) AS cantidad_envios_como_destinatario,
    COUNT(DISTINCT e_rem.nro_envio) + COUNT(DISTINCT e_dest.nro_envio) AS total_envios
FROM cliente c
JOIN localidad loc ON c.localidad_cod = loc.localidad_cod
JOIN provincia prov ON loc.provincia_cod = prov.provincia_cod
LEFT JOIN envio e_rem ON c.cliente_dni = e_rem.remitente_dni
LEFT JOIN envio e_dest ON c.cliente_dni = e_dest.destinatario_dni
GROUP BY c.cliente_dni, c.nombre, c.apellido, c.mail,
         c.telefono, loc.localidad_nombre, prov.provincia_nombre ;

-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `vista_envios_detalle`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vista_envios_detalle` AS SELECT 
    e.nro_envio,
    e.fecha_envio,
    e.peso_kg,
    tc.tipo_cont_nombre AS tipo_contenido,
    CONCAT(rem.nombre, ' ', rem.apellido) AS nombre_remitente,
    rem.cliente_dni AS dni_remitente,
    CONCAT(dest.nombre, ' ', dest.apellido) AS nombre_destinatario,
    dest.cliente_dni AS dni_destinatario,
    so.sucursal_nombre AS sucursal_origen,
    e.sucursal_orig_cod,
    sd.sucursal_nombre AS sucursal_destino,
    e.sucursal_dest_cod,
    CONCAT(loc.localidad_nombre, ', ', prov.provincia_nombre) AS ubicacion_entrega
FROM envio e
JOIN tipo_contenido tc ON e.tipo_cont_cod = tc.tipo_cont_cod
JOIN cliente rem ON e.remitente_dni = rem.cliente_dni
JOIN cliente dest ON e.destinatario_dni = dest.cliente_dni
JOIN sucursal so ON e.sucursal_orig_cod = so.sucursal_cod
JOIN sucursal sd ON e.sucursal_dest_cod = sd.sucursal_cod
JOIN direccion d ON e.direccion_entrega_id = d.direccion_id
JOIN localidad loc ON d.localidad_cod = loc.localidad_cod
JOIN provincia prov ON loc.provincia_cod = prov.provincia_cod ;

-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `vista_envios_pendientes`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vista_envios_pendientes` AS SELECT
    e.nro_envio,
    e.fecha_envio,
    e.peso_kg,
    tc.tipo_cont_nombre AS tipo_contenido,
    CONCAT(rem.nombre, ' ', rem.apellido) AS nombre_remitente,
    CONCAT(dest.nombre, ' ', dest.apellido) AS nombre_destinatario,
    so.sucursal_nombre AS sucursal_origen,
    sd.sucursal_nombre AS sucursal_destino,
    h_ultimo.estado AS ultimo_estado,
    h_ultimo.fecha_hora AS fecha_ultimo_estado
FROM envio e
JOIN tipo_contenido tc ON e.tipo_cont_cod = tc.tipo_cont_cod
JOIN cliente rem ON e.remitente_dni = rem.cliente_dni
JOIN cliente dest ON e.destinatario_dni = dest.cliente_dni
JOIN sucursal so ON e.sucursal_orig_cod = so.sucursal_cod
JOIN sucursal sd ON e.sucursal_dest_cod = sd.sucursal_cod
JOIN historial_estado h_ultimo ON h_ultimo.id_historial = (
    SELECT MAX(id_historial)
    FROM historial_estado
    WHERE nro_envio = e.nro_envio
)
WHERE h_ultimo.estado != 'Entregado' ;

-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `vista_historial_completo`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vista_historial_completo` AS SELECT
    h.id_historial,
    h.nro_envio,
    h.estado,
    h.fecha_hora,
    DATE_FORMAT(h.fecha_hora, '%d/%m/%Y %H:%i') AS fecha_formateada,
    s.sucursal_nombre,
    h.sucursal_cod,
    h.observacion,
    CONCAT(rem.nombre, ' ', rem.apellido) AS remitente,
    CONCAT(dest.nombre, ' ', dest.apellido) AS destinatario
FROM historial_estado h
JOIN sucursal s ON h.sucursal_cod = s.sucursal_cod
JOIN envio e ON h.nro_envio = e.nro_envio
JOIN cliente rem ON e.remitente_dni = rem.cliente_dni
JOIN cliente dest ON e.destinatario_dni = dest.cliente_dni ;

-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `vista_viajes_activos`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vista_viajes_activos` AS SELECT
    v.viaje_id,
    v.fecha_salida,
    CONCAT(c.nombre, ' ', c.apellido) AS nombre_chofer,
    c.chofer_legajo,
    c.chofer_tipo_licencia,
    ve.vehiculo_patente,
    ve.marca,
    ve.modelo,
    tv.tipo_veh_nombre AS tipo_vehiculo,
    COUNT(ve2.nro_envio) AS cantidad_envios
FROM viaje v
JOIN chofer c ON v.chofer_legajo = c.chofer_legajo
JOIN vehiculo ve ON v.vehiculo_patente = ve.vehiculo_patente
JOIN tipo_vehiculo tv ON ve.tipo_veh_cod = tv.tipo_veh_cod
LEFT JOIN viaje_envio ve2 ON v.viaje_id = ve2.viaje_id
WHERE v.fecha_llegada IS NULL
GROUP BY v.viaje_id, v.fecha_salida, c.nombre, c.apellido,
         c.chofer_legajo, c.chofer_tipo_licencia, ve.vehiculo_patente,
         ve.marca, ve.modelo, tv.tipo_veh_nombre ;

